import {
  ActivityIndicator,
  Pressable,
  StyleSheet,
  Text,
  View,
  useColorScheme,
  type PressableProps,
  type StyleProp,
  type TextStyle,
  type ViewStyle,
} from "react-native";
import Svg, { Circle, Path } from "react-native-svg";

// @mereka/sign-in v0.1.1 (sign-in-v0.1.1) - copied from https://cdn.jsdelivr.net/gh/Biji-Biji-Initiative/bbbi-mereka-brand-assets@sign-in-v0.1.1/packages/sign-in/react-native/SignInWithMereka.tsx. Upgrade by re-running the shadcn add with a newer tag.
