export type SignInWithMerekaVariant = "dark" | "light" | "brand" | "auto";
export type SignInWithMerekaSize = "sm" | "md" | "lg";
export type SignInWithMerekaShape = "rect" | "pill";
export type SignInWithMerekaLabel = keyof typeof SIGN_IN_LABELS;

export interface SignInWithMerekaColors {
  bg: string;
  fg: string;
  border: string;
  pressed: string;
}

// Same values as sign-in-with-mereka.css; "inverse" is what --auto uses in dark mode.
const PALETTES: Record<"dark" | "light" | "brand" | "inverse", SignInWithMerekaColors> = {
  dark: { bg: "#202321", fg: "#ffffff", border: "#202321", pressed: "#3d403e" },
  light: { bg: "#ffffff", fg: "#202321", border: "#dcded8", pressed: "#f3f3ef" },
  brand: { bg: "#267a7c", fg: "#ffffff", border: "#267a7c", pressed: "#206769" },
  inverse: { bg: "#f2f3ed", fg: "#171b19", border: "#f2f3ed", pressed: "#dfe0da" },
};

const SIZES: Record<SignInWithMerekaSize, { height: number; paddingX: number; fontSize: number }> = {
  sm: { height: 36, paddingX: 14, fontSize: 14 },
  md: { height: 44, paddingX: 18, fontSize: 16 },
  lg: { height: 52, paddingX: 20, fontSize: 16 },
};

const RECT_RADIUS = 10.4; // .65rem

export interface SignInWithMerekaProps extends Omit<PressableProps, "children" | "style"> {
  variant?: SignInWithMerekaVariant;
  size?: SignInWithMerekaSize;
  shape?: SignInWithMerekaShape;
  /** One of the approved labels. Prefer this over `labelText`. */
  label?: SignInWithMerekaLabel;
  /** Discouraged free-text override. Text naming "Authentik" is refused. */
  labelText?: string;
  fullWidth?: boolean;
  loading?: boolean;
  /** Theme without forking: override any of bg / fg / border / pressed. */
  colors?: Partial<SignInWithMerekaColors>;
  fontFamily?: string;
  style?: StyleProp<ViewStyle>;
  textStyle?: StyleProp<TextStyle>;
}

export function resolveSignInLabel(label: SignInWithMerekaLabel = "signin", labelText?: string): string {
  const text = (labelText ?? "").replace(/\s+/g, " ").trim();
  if (text && /authentik/i.test(text)) {
    console.warn(`[SignInWithMereka] "${text}" is not allowed (never name Authentik); using "${SIGN_IN_LABELS.signin}".`);
    return SIGN_IN_LABELS.signin;
  }
  return text || SIGN_IN_LABELS[label] || SIGN_IN_LABELS.signin;
}

/** The Mereka logomark. Do not recolour it independently of the label. */
export function MerekaMark({ color, height }: { color: string; height: number }) {
  return (
    <Svg width={height * MARK_ASPECT} height={height} viewBox={MARK_VIEW_BOX}>
      <Circle cx={MARK_CIRCLE.cx} cy={MARK_CIRCLE.cy} r={MARK_CIRCLE.r} fill={color} />
      <Path d={MARK_PATH} fill={color} />
    </Svg>
  );
}

export function SignInWithMereka({
  variant = "dark",
  size = "md",
  shape = "rect",
  label = "signin",
  labelText,
  fullWidth = false,
  loading = false,
  disabled,
  colors,
  fontFamily,
  style,
  textStyle,
  accessibilityLabel,
  ...rest
}: SignInWithMerekaProps) {
  const scheme = useColorScheme();
  const palette = variant === "auto" ? (scheme === "dark" ? "inverse" : "dark") : variant;
  const c = { ...PALETTES[palette], ...colors };
  const s = SIZES[size];
  const text = resolveSignInLabel(label, labelText);
  const inactive = Boolean(disabled) || loading;
  const markHeight = Math.round(s.fontSize * 1.1);

  return (
    <Pressable
      accessibilityRole="button"
      accessibilityLabel={accessibilityLabel ?? text}
      accessibilityState={{ disabled: inactive, busy: loading }}
      disabled={inactive}
      testID="mereka-signin"
      {...rest}
      style={({ pressed }) => [
        styles.base,
        {
          minHeight: s.height,
          paddingHorizontal: s.paddingX,
          borderRadius: shape === "pill" ? s.height / 2 : RECT_RADIUS,
          backgroundColor: pressed ? c.pressed : c.bg,
          borderColor: c.border,
          opacity: disabled && !loading ? 0.5 : 1,
        },
        fullWidth ? styles.full : styles.inline,
        style,
      ]}
    >
      <View style={[styles.icon, { width: Math.ceil(markHeight * MARK_ASPECT), height: markHeight }]}>
        {loading ? (
          <ActivityIndicator size="small" color={c.fg} />
        ) : (
          <MerekaMark color={c.fg} height={markHeight} />
        )}
      </View>
      <Text
        numberOfLines={1}
        style={[styles.label, { color: c.fg, fontSize: s.fontSize, fontFamily }, textStyle]}
      >
        {text}
      </Text>
    </Pressable>
  );
}

const styles = StyleSheet.create({
  base: {
    flexDirection: "row",
    alignItems: "center",
    justifyContent: "center",
    gap: 10,
    borderWidth: 1,
  },
  inline: { alignSelf: "flex-start" },
  full: { alignSelf: "stretch" },
  icon: { alignItems: "center", justifyContent: "center" },
  label: { fontWeight: "600", lineHeight: 20 },
});
